150	class WorksViewportRuntime {
151	  private readonly _pixelRatioMax: number;
152	
153	  constructor(pixelRatioMax: number) {
154	    this._pixelRatioMax = pixelRatioMax;
155	  }
156	
157	  read(): WorksViewportSnapshot {
158	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
159	    return {
160	      width: snapshot.viewportWidth,
161	      height: snapshot.viewportHeight,
162	      dpr: Math.min(snapshot.render.clampedPixelRatio, this._pixelRatioMax),
163	    };
164	  }
165	
166	  readHalfView(camera: THREE.Camera): WorksHalfViewBounds {
167	    if (camera instanceof THREE.OrthographicCamera) {
168	      return {
169	        hW: (camera.right - camera.left) * 0.5,
170	        hH: (camera.top - camera.bottom) * 0.5,
171	      };
172	    }
173	    const perspectiveCamera = camera as THREE.PerspectiveCamera;
174	    const fov = (perspectiveCamera.fov * Math.PI) / 180;
175	    const halfHeight = Math.tan(fov / 2) * perspectiveCamera.position.z;
176	    return {
177	      hW: halfHeight * perspectiveCamera.aspect,
178	      hH: halfHeight,
179	    };
180	  }
181	}
