183	class WorksHitRuntime {
184	  private readonly _raycaster = new THREE.Raycaster();
185	  private readonly _mouse2d = new THREE.Vector2();
186	
187	  resolve(
188	    camera: THREE.Camera,
189	    viewport: WorksViewportSnapshot,
190	    pointer: WorksPointerSample,
191	    meshes: THREE.Mesh[],
192	  ): THREE.Mesh | null {
193	    this._mouse2d.set(
194	      (pointer.x / viewport.width) * 2 - 1,
195	      -(pointer.y / viewport.height) * 2 + 1,
196	    );
197	    this._raycaster.setFromCamera(this._mouse2d, camera);
198	    const hit = this._raycaster.intersectObjects(meshes, false)[0];
199	    return (hit?.object as THREE.Mesh | undefined) ?? null;
200	  }
201	}
