349	class WorksMeshRuntime {
350	  create(
351	    scene: THREE.Scene,
352	    projects: ReadonlyArray<WorkProjectItem>,
353	    positions: ReadonlyArray<WorksScatterPosition>,
354	    config: WorkCanvasConfig,
355	  ): WorksSceneCardMeshResources {
356	    const cardSize: WorkCardSize = {
357	      w: config.cardWidth,
358	      h: config.cardHeight,
359	    };
360	    const meshes: THREE.Mesh[] = [];
361	    positions.forEach((position, placed) => {
362	      const project = projects[placed % projects.length];
363	      const detailPath = project?.detailPath ?? "/works";
364	      const mesh = WorkCard.createMesh(
365	        project,
366	        cardSize,
367	        detailPath,
368	        SCATTER_CARD_RENDER_OPTIONS,
369	      );
370	      mesh.position.set(position.x, position.y, 0);
371	      scene.add(mesh);
372	      meshes.push(mesh);
373	    });
374	    return {
375	      meshes,
376	      cardSize,
377	    };
378	  }
379	
380	  dispose(meshes: ReadonlyArray<THREE.Mesh>): void {
381	    meshes.forEach((mesh) => {
382	      const material = mesh.material as THREE.MeshBasicMaterial;
383	      material.map?.dispose();
384	      material.dispose();
385	      mesh.geometry.dispose();
386	    });
387	  }
388	}
