451	export class WorksSceneManager {
452	  private static readonly _dragStartThresholdPx = 10;
453	  /** 카테고리 전환 시 등장/퇴장 이징 길이(ms) — 전체 복귀 시 숨겨졌던 카드도 위치·투명도가 눈에 띄게 변함 */
454	  private static readonly _filterBlendMs = 480;
455	  private readonly root: ParentNode;
456	  private readonly config: WorkCanvasConfig;
457	  private readonly layout: WorkLayoutConstants;
458	  private readonly projects: ReadonlyArray<WorkProjectItem>;
459	  private readonly canvasId: string;
460	  private readonly rendererConfig: WorksRendererConfig;
461	  private readonly placeholderImage: string;
462	  private readonly introEntryState: WorksSceneManagerOptions["introEntryState"];
463	  private readonly viewportRuntime: WorksViewportRuntime;
464	  private readonly hitRuntime = new WorksHitRuntime();
465	  private readonly meshRuntime = new WorksMeshRuntime();
466	  private readonly thumbnailRuntime = new WorksThumbnailRuntime();
467	  private readonly cameraMotionRuntime: WorksCameraMotionRuntime;
468	  private readonly onSelect?: (detailPath: string) => void;
469	  private readonly onInteractionStart?: () => void;
470	  private canvas: HTMLCanvasElement | null = null;
471	  private scene: THREE.Scene | null = null;
472	  private camera: THREE.Camera | null = null;
473	  private renderer: THREE.WebGLRenderer | null = null;
474	  private meshes: THREE.Mesh[] = [];
475	  private rafId: number | null = null;
476	  private cleanup: Array<() => void> = [];
477	  private viewMode: WorksViewMode = "scatter";
478	  private clock: THREE.Clock | null = null;
479	  private activePointerId: number | null = null;
480	  private hovered: THREE.Mesh | null = null;
481	  private _prevHovered: THREE.Mesh | null = null;
482	  private _cardScale = 1;
483	  private _cardSize: WorkCardSize = { w: 10, h: 6.9 };
484	  private _isTouchPointer = false;
485	  private readonly _hoverVideo = new WorksHoverVideoRuntime();
486	  private mouseDownX = 0;
487	  private mouseDownY = 0;
488	  private mouseDownMesh: THREE.Mesh | null = null;
489	  private dragInteractionStarted = false;
490	  private readonly camPadX: number;
491	  private readonly camPadY: number;
492	  private scatterPositions: WorksScatterPosition[];
493	  private categoryScatterPositions: WorksScatterPosition[];
494	  private targetPositions: WorksScatterPosition[] = [];
495	  private interactiveMeshes: THREE.Mesh[] = [];
496	  private activeCategory: string | null;
497	  /** 직전 `applyCategory` 호출 직전의 필터 (전환 이징용) */
498	  private _filterPrevCategory: string | null = null;
499	  private _filterBlendStartMs = 0;
500	
501	  constructor(options: WorksSceneManagerOptions) {
502	    this.root = options.root;
503	    this.config = options.config;
504	    this.layout = options.layout;
505	    this.projects = options.projects;
506	    this.canvasId = options.canvasId;
507	    this.rendererConfig = options.renderer;
508	    this.placeholderImage = options.placeholderImage;
509	    this.introEntryState = options.introEntryState ?? null;
510	    this.onSelect = options.onSelect;
511	    this.onInteractionStart = options.onInteractionStart;
512	    this.activeCategory = options.initialCategory ?? null;
513	    this.camPadX = options.config.spreadX * 0.5 + 5;
514	    this.camPadY = options.config.spreadY * 0.5 + 5;
515	    this.viewportRuntime = new WorksViewportRuntime(options.pixelRatioMax);
516	    this.cameraMotionRuntime = new WorksCameraMotionRuntime(
517	      options.layout,
518	      this.camPadX,
519	      this.camPadY,
520	      options.config.camZ,
521	    );
522	    this.scatterPositions = buildScatterPositions(
523	      options.config.totalCards,
524	      options.config.spreadX,
525	      options.config.spreadY * 0.88,
526	    );
527	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
528	    this.targetPositions = [...this.scatterPositions];
529	  }
530	
531	  private _rebuildScatterPositions(): void {
532	    const scale = this._cardScale;
533	    this.scatterPositions = buildScatterPositions(
534	      this.config.totalCards,
535	      this.config.spreadX * scale,
536	      this.config.spreadY * 0.88 * scale,
537	    );
538	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
539	  }
540	
541	  init(): void {
542	    if (this.projects.length === 0) return;
543	    this.start();
544	  }
545	
546	  setViewMode(mode: WorksViewMode): void {
547	    if (this.viewMode === mode) return;
548	    this.viewMode = mode;
549	    if (mode === "grid") {
550	      this._hoverVideo.deactivate();
551	      this._prevHovered = null;
552	      this.hovered = null;
553	      this.mouseDownMesh = null;
554	      this.dragInteractionStarted = false;
555	      this.activePointerId = null;
556	      this.cameraMotionRuntime.endDrag();
557	      this.stopLoop();
558	      return;
559	    }
560	    this.cameraMotionRuntime.activateScatter();
561	    this.startLoop();
562	  }
563	
564	  applyCategory(category: string | null): void {
565	    if (this.activeCategory !== category) {
566	      this._filterPrevCategory = this.activeCategory;
567	      this._filterBlendStartMs = performance.now();
568	    }
569	    this.activeCategory = category;
570	    const scatterPositions =
571	      category === null ? this.scatterPositions : this.categoryScatterPositions;
572	    const nextPositions = [...this.scatterPositions];
573	    const nextInteractiveMeshes: THREE.Mesh[] = [];
574	    const visiblePositions: WorksScatterPosition[] = [];
575	    let visibleIndex = 0;
576	    for (let index = 0; index < this.meshes.length; index += 1) {
577	      const mesh = this.meshes[index];
578	      if (!mesh || !this.isMeshInCategory(mesh)) continue;
579	      nextInteractiveMeshes.push(mesh);
580	      const targetPosition = scatterPositions[visibleIndex] ?? this.scatterPositions[index];
581	      nextPositions[index] = targetPosition;
582	      visiblePositions.push(targetPosition);
583	      visibleIndex += 1;
584	    }
585	    this.targetPositions = nextPositions;
586	    this.interactiveMeshes = nextInteractiveMeshes;
587	    this._centerCameraOnVisiblePositions(visiblePositions);
588	    this.cameraMotionRuntime.setTargetZ(this.cameraMotionRuntime.readBaseCamZ());
589	    this.cameraMotionRuntime.setDynamicClamp(visiblePositions);
590	    if (this.hovered && !this.isMeshInCategory(this.hovered)) this.hovered = null;
591	  }
592	
593	  showCanvas(): void {
594	    if (!this.canvas) return;
595	    this.canvas.classList.remove("is-hidden", "is-transitioning-out");
596	    Aria.setHidden(this.canvas, false);
597	    this.canvas.style.opacity = "1";
598	  }
599	
600	  hideCanvas(): void {
601	    if (!this.canvas) return;
602	    this.canvas.classList.add("is-hidden");
603	    Aria.setHidden(this.canvas, true);
604	    this.canvas.style.opacity = "";
605	  }
606	
607	  /** 카테고리 필터·카메라 Z를 초기 스캐터 상태에 맞춤 (인트로 없이 즉시 호출) */
608	  applyInitialScatterState(): void {
609	    this.applyCategory(this.activeCategory);
610	    this.cameraMotionRuntime.setTargetZ(this.cameraMotionRuntime.readBaseCamZ());
611	  }
612	
613	  dispose(): void {
614	    this.stopLoop();
615	    this.cleanup.forEach((cleanup) => cleanup());
616	    this.cleanup = [];
617	    this.meshRuntime.dispose(this.meshes);
618	    this.meshes = [];
619	    this.interactiveMeshes = [];
620	    if (this.scene) {
621	      disposeObject3D(this.scene);
622	      this.scene.clear();
623	    }
624	    this.renderer?.dispose();
625	    this.renderer?.forceContextLoss();
626	    this.renderer = null;
627	    this.camera = null;
628	    this.scene = null;
629	    this.canvas = null;
630	    this.hovered = null;
631	    this._prevHovered = null;
632	    this.activePointerId = null;
633	    this._hoverVideo.dispose();
634	    WorkCard.offTextures();
