637	  update(delta: number): void {
638	    if (!this.camera || !this.scene) return;
639	    const camera = this.camera;
640	    this.cameraMotionRuntime.updateFrame(camera, delta);
641	
642	    // Hover video: activate / deactivate when hovered mesh changes
643	    if (this.hovered !== this._prevHovered) {
644	      if (this._prevHovered) this._hoverVideo.deactivate();
645	      if (this.hovered) {
646	        const userData = this.hovered.userData as WorkCardUserData;
647	        if (userData.proj.thumbnailVideo) {
648	          const material = this.hovered.material as THREE.MeshBasicMaterial;
649	          const texture = material.map;
650	          if (texture instanceof THREE.CanvasTexture) {
651	            this._hoverVideo.activate(
652	              this.hovered,
653	              texture,
654	              userData.proj.thumbnailVideo,
655	              userData.proj,
656	              this._cardSize,
657	              userData.loadedImage ?? null,
658	            );
659	          }
660	        }
661	      }
662	      this._prevHovered = this.hovered;
663	    }
664	    if (this._hoverVideo.isActive()) this._hoverVideo.drawFrame();
665	
666	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
667	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
668	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
669	    const isGridView = this.viewMode === "grid";
670	    const hover =
671	      this.hovered && this.isMeshInCategory(this.hovered) ? this.hovered : null;
672	    const blendT =
673	      this._filterBlendStartMs > 0
674	        ? Math.min(
675	            1,
676	            (performance.now() - this._filterBlendStartMs) /
677	              WorksSceneManager._filterBlendMs,
678	          )
679	        : 1;
680	    const filterEase = 1 - Math.pow(1 - blendT, 3);
681	    for (let index = 0; index < this.meshes.length; index += 1) {
682	      const mesh = this.meshes[index];
683	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
684	      const isActiveCategory = this.isMeshInCategory(mesh);
685	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
686	      const nowIn = isActiveCategory;
687	      let targetY = target.y;
688	      if (wasIn && !nowIn && blendT < 1) {
689	        targetY += (1 - filterEase) * 6.5;
690	      }
691	      if (!wasIn && nowIn && blendT < 1) {
692	        targetY -= (1 - filterEase) * 7.5;
693	      }
694	      mesh.position.x += (target.x - mesh.position.x) * positionFactor;
695	      mesh.position.y += (targetY - mesh.position.y) * positionFactor;
696	      mesh.position.z += (0 - mesh.position.z) * positionFactor;
697	      mesh.quaternion.copy(camera.quaternion);
698	      const opacityAnchor = isActiveCategory ? target : mesh.position;
699	      const distance = dist2d(
700	        camera.position.x,
701	        camera.position.y,
702	        opacityAnchor.x,
703	        opacityAnchor.y,
704	      );
705	      let targetOpacity = Math.max(0, Math.min(0.92, 1 - (distance - 8) * 0.025));
706	      if (!isActiveCategory) targetOpacity = 0;
707	      if (isActiveCategory && this.activeCategory !== null) {
708	        targetOpacity = Math.max(0.3, targetOpacity);
709	      }
710	      if (isGridView) targetOpacity = 0;
711	      if (hover) targetOpacity = hover === mesh ? 1 : targetOpacity * 0.55;
712	      if (nowIn && !wasIn) {
713	        targetOpacity *= filterEase;
714	      }
715	      const material = mesh.material as THREE.MeshBasicMaterial;
716	      material.opacity += (targetOpacity - material.opacity) * opacityFactor;
717	      const steadyScale = (hover === mesh ? 1.06 : 1) * this._cardScale;
718	      mesh.scale.x += (steadyScale - mesh.scale.x) * scaleFactor;
719	      mesh.scale.y += (steadyScale - mesh.scale.y) * scaleFactor;
720	    }
721	  }
