919	  private startLoop(): void {
920	    if (this.rafId !== null) return;
921	    if (!this.camera || !this.renderer || !this.scene) return;
922	    this.clock = new THREE.Clock();
923	    this.clock.start();
924	    const animate = (): void => {
925	      if (!this.camera || !this.renderer || !this.scene || !this.clock) {
926	        this.rafId = null;
927	        return;
928	      }
929	      this.rafId = FrameScheduler.request(animate);
930	      const delta = Math.min(this.clock.getDelta(), MAX_DELTA_SECONDS);
931	      this.update(delta);
932	      this.renderer.render(this.scene, this.camera);
933	    };
934	    animate();
935	  }
936	
937	  private stopLoop(): void {
938	    if (this.rafId !== null) {
939	      FrameScheduler.cancel(this.rafId);
940	      this.rafId = null;
941	    }
942	    this.clock?.stop();
943	    this.clock = null;
944	  }
945	
946	  private _resetPointerInteraction(pointerId: number): void {
947	    this.mouseDownMesh = null;
948	    this.dragInteractionStarted = false;
949	    this.cameraMotionRuntime.endDrag();
950	    this.activePointerId = null;
951	    if (this.canvas?.hasPointerCapture(pointerId)) {
952	      this.canvas.releasePointerCapture(pointerId);
953	    }
954	  }
