956	  private isMeshInCategory(mesh: THREE.Mesh): boolean {
957	    if (this.activeCategory == null) return true;
958	    const userData = mesh.userData as WorkCardUserData;
959	    return userData.proj.category === this.activeCategory;
960	  }
961	
962	  private _meshIncludedInFilter(mesh: THREE.Mesh, category: string | null): boolean {
963	    if (category == null) return true;
964	    const userData = mesh.userData as WorkCardUserData;
965	    return userData.proj.category === category;
966	  }
967	
968	  private _centerCameraOnVisiblePositions(
969	    positions: ReadonlyArray<WorksScatterPosition>,
970	  ): void {
971	    const center = this._readVisiblePositionsCenter(positions);
972	    this.cameraMotionRuntime.setTargetPosition(center.x, center.y);
973	  }
974	
975	  private _readVisiblePositionsCenter(
976	    positions: ReadonlyArray<WorksScatterPosition>,
977	  ): WorksScatterPosition {
978	    if (positions.length === 0) {
979	      return { x: 0, y: 0 };
980	    }
981	    let minX = positions[0]?.x ?? 0;
982	    let maxX = minX;
983	    let minY = positions[0]?.y ?? 0;
984	    let maxY = minY;
985	    for (let index = 1; index < positions.length; index += 1) {
986	      const position = positions[index];
987	      if (!position) continue;
988	      minX = Math.min(minX, position.x);
989	      maxX = Math.max(maxX, position.x);
990	      minY = Math.min(minY, position.y);
991	      maxY = Math.max(maxY, position.y);
992	    }
993	    return {
994	      x: (minX + maxX) * 0.5,
995	      y: (minY + maxY) * 0.5,
996	    };
997	  }
998	}
