32	function createWorksEngine(
33	  canvasId: string,
34	  canvasElement?: HTMLCanvasElement | null,
35	): Engine {
36	  const three = WorksSceneDefinition.createThreeConfig(canvasId);
37	  return new Engine({
38	    canvasId: three.canvasId,
39	    canvasElement,
40	    camera: three.camera,
41	    cameraTarget: three.cameraTarget,
42	    renderer: three.renderer,
43	    pixelRatioMax: three.pixelRatioMax,
44	    shadowMap: three.shadowMap,
45	    renderBudget: three.renderBudget,
