51	/** 별도 캔버스에 메인 배경(우주)만 재생 — works 메인 캔버스와 분리 */
52	export class WorksBackgroundRuntime {
53	  private static readonly _readyTimeoutMs = 2000;
54	  private _engine: Engine | null = null;
55	  private _objectSetup: ObjectSetup | null = null;
56	  private _canvasElement: HTMLCanvasElement | null = null;
57	  private _readyFrameId: number | null = null;
58	
59	  async run(canvasId: string, canvasElement: HTMLCanvasElement): Promise<void> {
60	    if (this._engine && this._canvasElement === canvasElement) return;
61	    if (this._engine) {
62	      this.dispose();
63	    }
64	    const engine = createWorksEngine(canvasId, canvasElement);
65	    if (!engine.init()) return;
66	    this._engine = engine;
67	    this._canvasElement = canvasElement;
68	    this._objectSetup = new ObjectSetup();
69	    const config = WorksSceneDefinition.createBackgroundPageConfig(canvasId);
70	    await this._objectSetup.init(engine, config);
71	    const runtimeState = WorksSceneDefinition.createBackgroundRuntimeState();
72	    engine
73	      .getBackgroundManager()
74	      ?.setRuntimeState(mainBackground, runtimeState);
75	    engine.start(() => undefined, () => undefined);
76	    await this._waitUntilReady(engine);
77	  }
78	
79	  dispose(): void {
80	    if (this._readyFrameId !== null) {
81	      FrameScheduler.cancel(this._readyFrameId);
82	      this._readyFrameId = null;
83	    }
84	    this._objectSetup?.dispose();
85	    this._objectSetup = null;
86	    this._engine?.dispose();
87	    this._engine = null;
88	    this._canvasElement = null;
89	  }
90	
91	  private _waitUntilReady(engine: Engine): Promise<void> {
92	    return new Promise<void>((resolve, reject) => {
93	      const startedAt = resolveTimestamp();
94	      const tick = (): void => {
95	        if (this._engine !== engine) {
96	          this._readyFrameId = null;
97	          resolve();
98	          return;
99	        }
100	        const backgroundManager = engine.getBackgroundManager();
101	        if (backgroundManager?.hasRenderedFrame()) {
102	          this._readyFrameId = null;
103	          resolve();
104	          return;
105	        }
106	        if (
107	          resolveTimestamp() - startedAt > WorksBackgroundRuntime._readyTimeoutMs
108	        ) {
109	          this._readyFrameId = null;
110	          reject(
111	            new Error(
112	              "[WorksBackgroundRuntime._waitUntilReady] Background render timed out.",
113	            ),
114	          );
115	          return;
116	        }
117	        this._readyFrameId = FrameScheduler.request(tick);
118	      };
119	      this._readyFrameId = FrameScheduler.request(tick);
120	    });
121	  }
122	}
123	
124	export class WorksIntroPlaybackRuntime {
125	  private _engine: Engine | null = null;
126	  private _objectSetup: ObjectSetup | null = null;
127	  private _frameId: number | null = null;
128	  private _disposed = false;
129	
130	  async run(
131	    canvasId: string,
132	    canvasElement: HTMLCanvasElement | null,
133	  ): Promise<SceneFromState | null> {
134	    if (!(canvasElement instanceof HTMLCanvasElement)) return null;
135	    const introConfig = readWorksTheatreConfig();
136	    if (introConfig.steps.length === 0) return null;
137	
138	    await ensureWorksTheatreRuntimeReady();
139	    if (this._disposed) return null;
140	
141	    const firstStep = introConfig.steps[0] ?? null;
142	    const initialState = WorksSceneDefinition.createInitialState(
143	      readWorksTheatreStepState(firstStep, 0),
144	    );
145	    const engine = createWorksEngine(canvasId, canvasElement);
146	    if (!engine.init()) return null;
147	    this._engine = engine;
148	
149	    this._objectSetup = new ObjectSetup();
150	    const config = WorksSceneDefinition.createIntroPageConfig(canvasId, initialState);
151	    await this._objectSetup.init(engine, config);
152	    if (this._disposed || this._engine !== engine) return null;
153	
154	    engine.setState(initialState);
155	    engine.start(() => undefined, () => undefined);
156	
157	    for (const step of introConfig.steps) {
158	      if (this._disposed || this._engine !== engine) return null;
159	      await this._playStep(step);
160	    }
161	
162	    const lastStep = introConfig.steps[introConfig.steps.length - 1] ?? null;
163	    return readWorksTheatreStepState(lastStep, 1);
164	  }
165	
166	  dispose(): void {
167	    this._disposed = true;
168	    if (this._frameId !== null) {
169	      FrameScheduler.cancel(this._frameId);
170	      this._frameId = null;
171	    }
172	    this._objectSetup?.dispose();
173	    this._objectSetup = null;
174	    this._engine?.dispose();
175	    this._engine = null;
176	  }
177	
178	  private _playStep(step: WorksIntroSheetStepConfig): Promise<void> {
179	    return new Promise<void>((resolve) => {
180	      const engine = this._engine;
181	      if (!engine || this._disposed) {
182	        resolve();
183	        return;
184	      }
185	      const startedAt = resolveTimestamp();
186	      const durationMs = Math.max(1, step.durationMs);
187	      const tick = (): void => {
188	        if (this._disposed || this._engine !== engine) {
189	          this._frameId = null;
190	          resolve();
191	          return;
192	        }
193	        const elapsed = resolveTimestamp() - startedAt;
194	        const progress = Math.min(1, elapsed / durationMs);
195	        const easedProgress = applyWorksIntroEase(progress);
196	        engine.setState(
197	          WorksSceneDefinition.createInitialState(
198	            readWorksTheatreStepState(step, easedProgress),
199	          ),
200	        );
201	        if (progress >= 1) {
202	          this._frameId = null;
203	          resolve();
204	          return;
205	        }
206	        this._frameId = FrameScheduler.request(tick);
207	      };
208	      tick();
209	    });
210	  }
211	}
